document.addEventListener("DOMContentLoaded", () => {
  // Obtener el botón para descargar el PDF
  const btnPDF = document.getElementById("btnDescargarPDF");

  // Si no se encuentra el botón, no hacer nada
  if (!btnPDF) return;

  // Escuchar el evento de clic en el botón
  btnPDF.addEventListener("click", () => {
    // Crear una nueva instancia del objeto jsPDF
    const doc = new jspdf.jsPDF();

    // Obtener la fecha actual en formato local
    const date = new Date().toLocaleDateString();
    // Nombre de la empresa que aparecerá en el documento
    const nombreEmpresa = "UV Energía Solar";

    // Obtener los valores de potencia, generación, paneles, baterías e inversores de los elementos del DOM
    const potencia = document.getElementById("potencia")?.innerText || "N/A";
    const generacion =
      document.getElementById("generacion")?.innerText || "N/A";
    const paneles = document.getElementById("paneles")?.innerText || "N/A";
    const baterias = document.getElementById("baterias")?.innerText || "N/A";
    const inversores =
      document.getElementById("inversores")?.innerText || "N/A";

    // Establecer el tamaño de la fuente
    doc.setFontSize(16);
    // doc.addImage(logoBase64, 'PNG', 150, 10, 40, 20); // ← espacio reservado para logo
    // Agregar el nombre de la empresa al documento
    doc.text(nombreEmpresa, 20, 20);
    // Establecer el tamaño de la fuente para el siguiente texto
    doc.setFontSize(12);
    // Agregar título y fecha de la cotización
    doc.text("Cotización de Sistema Solar Fotovoltaico", 20, 30);
    doc.text("Fecha: " + date, 20, 40);

    // Agregar los detalles de la cotización al documento
    doc.text("\u2022 Potencia recomendada: " + potencia, 20, 60);
    doc.text("\u2022 Generación mensual estimada: " + generacion, 20, 70);
    doc.text("\u2022 Paneles solares necesarios: " + paneles, 20, 80);
    doc.text("\u2022 Baterías necesarias: " + baterias, 20, 90);
    doc.text("\u2022 Inversores necesarios: " + inversores, 20, 100);

    // Establecer el tamaño de la fuente para el pie de página
    doc.setFontSize(10);
    // Agregar mensaje de agradecimiento
    doc.text("Gracias por confiar en UV Energía Solar.", 20, 150);
    doc.text(
      "Esta cotización es orientativa según los datos que proporcionaste.",
      20,
      158
    );
    doc.text(
      "Para asesoramiento profesional, contactanos por WhatsApp:",
      20,
      168
    );
    // Cambiar el color del texto a azul para el enlace
    doc.setTextColor(0, 102, 204);
    // Agregar un enlace de WhatsApp
    doc.textWithLink("+54 9 3865 58-6322", 20, 178, {
      url: "https://wa.me/5493865586322?text=Hola,%20vi%20mi%20cotizaci%C3%B3n%20solar%20desde%20su%20sitio%20y%20quiero%20asesoramiento.",
    });

    // Guardar el archivo PDF con el nombre "cotizacion-solar.pdf"
    doc.save("cotizacion-solar.pdf");
  });
});
